import React, { useState } from 'react';
import { register } from '../api';

export default function Register({ onRegister }) {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [busy, setBusy] = useState(false);

  async function submit(e) {
    e.preventDefault();
    setBusy(true);
    try {
      const res = await register(email, password);
      // backend may return plain text 'OK' or a JSON, handle both:
      if (res === 'OK' || (res && res.message)) {
        alert('Registration successful — please login.');
        onRegister();
      } else {
        alert('Registration error: ' + JSON.stringify(res));
      }
    } catch (err) {
      alert('Register error: ' + err.message);
    } finally { setBusy(false); }
  }

  return (
    <div className="card form">
      <h2>Register</h2>
      <form onSubmit={submit}>
        <label>Email</label>
        <input value={email} onChange={e=>setEmail(e.target.value)} type="email" required />
        <label>Password</label>
        <input value={password} onChange={e=>setPassword(e.target.value)} type="password" required minLength={4} />
        <button type="submit" disabled={busy}>{busy ? 'Saving...' : 'Sign Up'}</button>
      </form>
    </div>
  );
}
